 namespace filesystem {

 std::filesystem::path GetExecutablePath() {
+#if defined(__MINGW32__)
+  // A narrow main() does not initialize the CRT's wide program-path slot.
+  // The Windows process image path is independent of that CRT entry point.
+  std::wstring path(260, L'\0');
+  for (;;) {
+    const DWORD length = GetModuleFileNameW(nullptr, path.data(), static_cast<DWORD>(path.size()));
+    if (length == 0) return {};
+    if (length < path.size()) {
+      path.resize(length);
+      return std::filesystem::path(path);
+    }
+    if (path.size() == 32768) return {};
+    path.resize(path.size() < 16384 ? path.size() * 2 : 32768);
+  }
+#else
   wchar_t* path;
   auto error = _get_wpgmptr(&path);
   return !error ? std::filesystem::path(path) : std::filesystem::path();
+#endif
 }

